package cn.sixnine.filmlog;
import android.content.ContentValues;
import android.database.Cursor;
import java.util.*;

/** User-maintained film definitions. Rolls and stock batches retain their own historical snapshots. */
final class FilmStockStore {
    static final class Stock {String id,brand,name,process,power,formats;String isoLabel="",search="",notice="",category="";int iso;boolean archived,builtin;String title(){return brand.isEmpty()||name.toLowerCase(Locale.ROOT).startsWith(brand.toLowerCase(Locale.ROOT)+" ")?name:brand+" "+name;}}
    private static ArrayList<Stock> sourceFilms;
    static synchronized ArrayList<Stock> builtins(android.content.Context context){
        if(sourceFilms==null){ArrayList<Stock> loaded=new ArrayList<>();try(java.io.InputStream in=context.getAssets().open("filmer-catalog.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){
            byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);
            org.json.JSONArray rows=new org.json.JSONArray(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));Set<String> ids=new HashSet<>();
            for(int i=0;i<rows.length();i++){org.json.JSONObject row=rows.getJSONObject(i);Stock stock=new Stock();stock.id=row.getString("id");if(!stock.id.matches("filmer:[a-zA-Z0-9_-]+")||!ids.add(stock.id))throw new IllegalArgumentException("来源片种ID无效");stock.brand=row.getString("brand");stock.name=row.getString("name");stock.iso=row.getInt("iso");if(stock.iso<0||stock.iso>102400)throw new IllegalArgumentException("来源ISO无效");stock.isoLabel=row.optString("iso_label");stock.process=row.getString("process");stock.formats=row.getString("formats");stock.power="";stock.builtin=true;stock.search=row.optString("search");stock.notice=row.optString("notice");stock.category=row.optString("category");loaded.add(stock);}
        }catch(java.io.IOException|org.json.JSONException invalid){throw new IllegalStateException("来源片种目录无效",invalid);}sourceFilms=loaded;}
        ArrayList<Stock> result=OriginalCatalog.films(context);result.addAll(sourceFilms);return result;
    }
    static Stock builtin(android.content.Context context,String id){for(Stock stock:builtins(context))if(stock.id.equals(id))return stock;throw new IllegalArgumentException("片种ID不在内置目录中，请重新选择");}
    static String isoText(Stock stock){return stock.isoLabel.isEmpty()?(stock.iso==0?"ISO待填写":"ISO "+stock.iso):"ISO "+stock.isoLabel;}
    private final LogStore logs;FilmStockStore(LogStore logs){this.logs=logs;}
    static String text(String value,int limit,String label){if(value==null||value.length()>limit)throw new IllegalArgumentException(label+"过长或无效");return value.trim();}
    static String formats(String value){LinkedHashSet<String> values=new LinkedHashSet<>();for(String part:text(value,500,"规格").split("[,，;；]")){part=part.trim();if(!part.isEmpty()){if(part.length()>60)throw new IllegalArgumentException("单个规格不能超过60字");values.add(part);}}return String.join(",",values);}
    static void validate(Stock stock){if(stock.id==null||!UUID.fromString(stock.id).toString().equals(stock.id))throw new IllegalArgumentException("片种标识无效");text(stock.brand,200,"品牌");CatalogStore.required(stock.name,"片种名称");text(stock.process,80,"冲洗工艺");if(stock.iso<1||stock.iso>102400)throw new IllegalArgumentException("ISO须在1至102400之间");formats(stock.formats);if(stock.power==null)throw new IllegalArgumentException("倒易律参数无效");if(!stock.power.trim().isEmpty())try{double power=Double.parseDouble(stock.power);if(!Double.isFinite(power)||power<1||power>3)throw new NumberFormatException();}catch(NumberFormatException invalid){throw new IllegalArgumentException("倒易律p请留空或填写1至3之间的数");}}
    static boolean matches(Stock stock,String format){if(stock.formats.isEmpty()||format==null||format.trim().isEmpty())return true;for(String choice:stock.formats.split(","))if(choice.replace(" ","").equalsIgnoreCase(format.replace(" ","")))return true;return false;}
    ArrayList<Stock> list(boolean archived){ArrayList<Stock> result=new ArrayList<>();try(Cursor row=logs.getReadableDatabase().query("film_stocks",null,"archived=?",new String[]{archived?"1":"0"},null,null,"brand COLLATE NOCASE,name COLLATE NOCASE,id")){while(row.moveToNext()){Stock stock=new Stock();stock.id=LogStore.str(row,"id");stock.brand=LogStore.str(row,"brand");stock.name=LogStore.str(row,"name");stock.iso=LogStore.num(row,"iso");stock.process=LogStore.str(row,"process");stock.power=LogStore.str(row,"reciprocity_p");stock.formats=LogStore.str(row,"formats");stock.archived=LogStore.num(row,"archived")!=0;result.add(stock);}}return result;}
    ArrayList<Stock> all(android.content.Context context,boolean archived){ArrayList<Stock> result=archived?new ArrayList<>():builtins(context);result.addAll(list(archived));return result;}
    Stock choose(android.content.Context context,String id,String format){if(id!=null&&(id.startsWith("original:")||id.startsWith("filmer:"))){for(Stock stock:builtins(context))if(stock.id.equals(id)){if(!matches(stock,format))throw new IllegalArgumentException("片种不支持所选规格，请重新选择");return stock;}throw new IllegalArgumentException("片种已变化，请重新选择");}return choose(id,format);}
    Stock get(String id){for(boolean archived:new boolean[]{false,true})for(Stock stock:list(archived))if(stock.id.equals(id))return stock;throw new IllegalArgumentException("所选片种已变化，请重新选择");}
    Stock choose(String id,String format){Stock stock=get(id);if(stock.archived||!matches(stock,format))throw new IllegalArgumentException("片种已归档或不支持所选规格，请重新选择");return stock;}
    void save(Stock stock){validate(stock);ContentValues row=new ContentValues();row.put("brand",stock.brand.trim());row.put("name",stock.name.trim());row.put("iso",stock.iso);row.put("process",stock.process.trim());row.put("reciprocity_p",stock.power.trim());row.put("formats",formats(stock.formats));android.database.sqlite.SQLiteDatabase db=logs.getWritableDatabase();db.beginTransaction();try{boolean exists;try(Cursor previous=db.rawQuery("SELECT id FROM film_stocks WHERE id=?",new String[]{stock.id})){exists=previous.moveToFirst();}if(exists)db.update("film_stocks",row,"id=?",new String[]{stock.id});else{row.put("id",stock.id);row.put("archived",0);row.put("created_at",System.currentTimeMillis());db.insertOrThrow("film_stocks",null,row);}db.setTransactionSuccessful();}finally{db.endTransaction();}}
    void archive(String id,boolean archived){get(id);ContentValues row=new ContentValues();row.put("archived",archived?1:0);logs.getWritableDatabase().update("film_stocks",row,"id=?",new String[]{id});}
}
